import React, { useMemo, useState } from 'react';
import {
  overlayStyle,
  modalStyle,
  modalTitleStyle,
  modalFormStyle,
  modalInputStyle,
  modalLabelStyle,
  modalActionsStyle,
  modalSubmitButtonStyle,
  modalCancelButtonStyle,
  modalErrorStyle,
  unionOptionStyle,
} from '../styles/addRelativeStyles';
import { addSpouse, addChild, addParent, findUnionOptions } from '../services/relativeService';

const TITLES = {
  spouse: 'მეუღლის დამატება',
  child: 'შვილის დამატება',
  parent: 'მშობლის დამატება',
};

const emptyForm = {
  fname: '',
  lname: '',
  nName: '',
  gender: '',
  birthDate: '',
  deathDate: '',
  birthPlace: '',
  role: '',
};

const AddRelativeModal = ({ kind, personId, members, relationships, onClose, onSuccess }) => {
  const unionOptions = useMemo(
    () => (kind === 'child' ? findUnionOptions(personId, members, relationships) : []),
    [kind, personId, members, relationships]
  );

  const [chosenMergePointId, setChosenMergePointId] = useState(
    unionOptions.length === 1 ? unionOptions[0].mergePointId : null
  );
  const [showUnionPicker, setShowUnionPicker] = useState(unionOptions.length > 1);
  const [form, setForm] = useState(emptyForm);
  const [error, setError] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const handleChange = (field) => (e) => setForm((f) => ({ ...f, [field]: e.target.value }));

  const toMemberData = () => ({
    fname: form.fname || null,
    lname: form.lname || null,
    nName: form.nName || null,
    gender: form.gender || null,
    birthDate: form.birthDate || null,
    deathDate: form.deathDate || null,
    birthPlace: form.birthPlace || null,
    role: form.role || null,
  });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSubmitting(true);
    try {
      const memberData = toMemberData();
      if (kind === 'spouse') {
        await addSpouse(personId, memberData);
      } else if (kind === 'child') {
        await addChild(personId, memberData, members, relationships, chosenMergePointId);
      } else if (kind === 'parent') {
        await addParent(personId, memberData, members, relationships);
      }
      onSuccess();
    } catch (err) {
      setError(err.message);
    } finally {
      setSubmitting(false);
    }
  };

  if (showUnionPicker) {
    return (
      <div style={overlayStyle} onClick={onClose}>
        <div style={modalStyle} onClick={(e) => e.stopPropagation()}>
          <h2 style={modalTitleStyle}>აირჩიეთ კავშირი</h2>
          <div style={modalFormStyle}>
            {unionOptions.map((opt) => (
              <button
                key={opt.mergePointId}
                style={unionOptionStyle}
                onClick={() => {
                  setChosenMergePointId(opt.mergePointId);
                  setShowUnionPicker(false);
                }}
              >
                {opt.label}
              </button>
            ))}
          </div>
          <div style={modalActionsStyle}>
            <button style={modalCancelButtonStyle} onClick={onClose}>
              გაუქმება
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div style={overlayStyle} onClick={onClose}>
      <div style={modalStyle} onClick={(e) => e.stopPropagation()}>
        <h2 style={modalTitleStyle}>{TITLES[kind]}</h2>
        <form style={modalFormStyle} onSubmit={handleSubmit}>
          <input
            style={modalInputStyle}
            placeholder="სახელი"
            value={form.fname}
            onChange={handleChange('fname')}
            required
          />
          <input
            style={modalInputStyle}
            placeholder="გვარი"
            value={form.lname}
            onChange={handleChange('lname')}
          />
          <input
            style={modalInputStyle}
            placeholder="მეტსახელი"
            value={form.nName}
            onChange={handleChange('nName')}
          />
          <select style={modalInputStyle} value={form.gender} onChange={handleChange('gender')} required>
            <option value="" disabled>
              სქესი
            </option>
            <option value="კაცი">კაცი</option>
            <option value="ქალი">ქალი</option>
          </select>
          <label style={modalLabelStyle}>დაბადების თარიღი</label>
          <input
            style={modalInputStyle}
            type="date"
            value={form.birthDate}
            onChange={handleChange('birthDate')}
          />
          <label style={modalLabelStyle}>გარდაცვალების თარიღი</label>
          <input
            style={modalInputStyle}
            type="date"
            value={form.deathDate}
            onChange={handleChange('deathDate')}
          />
          <input
            style={modalInputStyle}
            placeholder="დაბადების ადგილი"
            value={form.birthPlace}
            onChange={handleChange('birthPlace')}
          />
          <input
            style={modalInputStyle}
            placeholder="როლი (არასავალდებულო)"
            value={form.role}
            onChange={handleChange('role')}
          />
          {error && <p style={modalErrorStyle}>{error}</p>}
          <div style={modalActionsStyle}>
            <button type="button" style={modalCancelButtonStyle} onClick={onClose}>
              გაუქმება
            </button>
            <button type="submit" style={modalSubmitButtonStyle} disabled={submitting}>
              {submitting ? '...' : 'დამატება'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AddRelativeModal;
