import React, { useEffect, useState, useRef } from 'react';
import Filters from './Filters';
import SearchInputs from './SearchInputs';
import CountDisplay from './CountDisplay';
import AuthStatus from './AuthStatus';
import NodeActionsMenu from './NodeActionsMenu';
import AddRelativeModal from './AddRelativeModal';
import EditMemberModal from './EditMemberModal';
import NodeInfoPopup from './NodeInfoPopup';
import { useAuth } from '../context/AuthContext';
import { fetchFamilyTree, fetchSpouseData } from '../services/familyTreeService';
import { removeMember } from '../services/relativeService';
import { initializeCytoscape, updateCyOnFilter } from '../cytoscope/setupGraph';
import '../styles/FamilyTreeGraphStyles.css';
import { nodeActionButtonStyle, popupToggleStyle } from '../styles/addRelativeStyles';
import {
  layoutContainerStyle,
  headerStyle,
  graphContainerStyle,
  graphPreviewContainerStyle
} from '../styles/familyTreeStyles';

const INFO_POPUP_STORAGE_KEY = 'ft_show_info_popup';

const FamilyTreeGraph = () => {
  const { isAdmin } = useAuth();
  const [elements, setElements] = useState([]);
  const [allElements, setAllElements] = useState([]);
  const [connections, setConnections] = useState([]);
  const [allConnections, setAllConnections] = useState([]);
  const [cyInstance, setCyInstance] = useState(null);
  const [selectedPersonId, setSelectedPersonId] = useState(null);
  // eslint-disable-next-line no-unused-vars
  const [viewportTick, setViewportTick] = useState(0); // bumped on pan/zoom to force a re-render
  const [menuOpen, setMenuOpen] = useState(false);
  const [relativeAction, setRelativeAction] = useState(null);
  const [editingMember, setEditingMember] = useState(null);
  const [showInfoPopup, setShowInfoPopup] = useState(() => {
    const saved = localStorage.getItem(INFO_POPUP_STORAGE_KEY);
    return saved === null ? true : saved === 'true';
  });
  const [popupDismissed, setPopupDismissed] = useState(false);

  const [selectedLname, setSelectedLname] = useState('');
  const [allLnames, setAllLnames] = useState([]);
  const [filteredCount, setFilteredCount] = useState(0);

  const [previewOpen, setPreviewOpen] = useState(true);

  const togglePreview = () => {
    setPreviewOpen(prev => !prev);
  };

  const lastResultsRef = useRef([]); // ბოლოს ნაპოვნი ნოდები
  const currentIndexRef = useRef(0); // ამჟამინდელი პოზიცია

  const previewStyle = {
    ...graphPreviewContainerStyle,
    width: previewOpen ? '600px' : '40px',
    transition: 'width 0.4s ease',
  };

  useEffect(() => {
    localStorage.setItem(INFO_POPUP_STORAGE_KEY, String(showInfoPopup));
  }, [showInfoPopup]);

  // viewportTick has no reader below by design — bumping it just forces the re-render
  // that recomputes node screen positions from the live cytoscape viewport (pan/zoom).
  const getNodeScreenPosition = (personId) => {
    if (!cyInstance || personId == null) return null;
    const node = cyInstance.getElementById(String(personId));
    if (!node || node.empty()) return null;
    const container = cyInstance.container();
    const rect = container.getBoundingClientRect();
    const pos = node.renderedPosition();
    return { x: rect.left + pos.x, y: rect.top + pos.y };
  };

  const loadTree = () => {
    fetchFamilyTree().then(data => {
      setElements(data.members);
      setAllElements(data.members);
      setConnections(data.relationships);
      setAllConnections(data.relationships);
      const uniqueLnames = [...new Set(data.members.map(m => m.lname).filter(Boolean))];
      setAllLnames(uniqueLnames);
    });
  };

  useEffect(() => {
    loadTree();
  }, []);
  useEffect(() => {
    const count = elements.filter(m => m.role != 'MergePoint').length;
    setFilteredCount(count);
  }, [elements]);

  useEffect(() => {
    if (!elements.length || !connections.length) return;

    // destroy old instance if exists
    if (cyInstance) {
      cyInstance.destroy();
    }

    // create new instance
    const newCy = initializeCytoscape(elements, connections);
    setCyInstance(newCy);

    // არ გჭირდება filter აქ, რადგან elements უკვე გაფილტრულია ან თავიდან ჩაიტვირთა

    return () => {
      if (newCy) {
        newCy.destroy();
      }
    };
  }, [elements, connections]);

  const handleLnameFilter = (lname) => {

    const filtered = lname
      ? elements.filter(m => m.lname === lname)
      : elements;

    const countWithoutMerge = filtered.filter(m => !m.mergePoint).length;

    setFilteredCount(countWithoutMerge);

    setSelectedLname(lname);

    if (!cyInstance) return;

    // Hide all nodes and edges initially
    cyInstance.nodes().forEach(node => node.hide());
    cyInstance.edges().forEach(edge => edge.hide());

    if (!lname) {
      // Show all nodes and edges if no surname is selected
      cyInstance.nodes().forEach(node => node.show());
      cyInstance.edges().forEach(edge => edge.show());
      cyInstance.layout({ name: 'dagre' }).run();
      return;
    }

    const matchingNodes = cyInstance.nodes().filter(n => n.data('lname') === lname);

    if (matchingNodes.length === 0) return;

    const findTopAncestor = (node) => {
      let current = node;
      while (current.incomers('edge').length > 0) {
        current = current.incomers('edge')[0].source();
        if (!current.data('lname') || current.data('lname') !== lname) {
          break;
        }
      }
      return current;
    };

    const topAncestors = matchingNodes.map(findTopAncestor);
    const uniqueTopAncestors = [...new Set(topAncestors.map(n => n.id()))];

    const showDescendants = (node) => {
      node.show();
      node.outgoers('edge').forEach(edge => {
        edge.show();
        const target = edge.target();
        if (target.data('role') !== 'MergePoint') {
          target.show();
          showDescendants(target);
        }
      });
    };

    uniqueTopAncestors.forEach(id => {
      const root = cyInstance.getElementById(id);
      root.show();
      showDescendants(root);

      // Additionally, show spouses connected to MergePoints
      const mergePointConnections = cyInstance.edges().filter(edge => {
        const sourceNode = edge.source();
        const targetNode = edge.target();
        return (sourceNode.id() === id && sourceNode.data('role') === 'MergePoint') ||
          (targetNode.id() === id && targetNode.data('role') === 'MergePoint');
      });

      mergePointConnections.forEach(edge => {
        edge.show();
        edge.source().show();
        edge.target().show();
      });
    });

    cyInstance.layout({ name: 'dagre' }).run();
  };
  const handleSearchGOTO = () => {
    const searchValue = document.getElementById("nodeSearch").value.trim().toLowerCase();
    if (!cyInstance || !searchValue) return;

    cyInstance.nodes().removeClass("highlighted");

    const searchWords = searchValue.split(" ").filter(Boolean);

    let found = cyInstance.nodes().filter(n => {
      const fullName = (n.data("fname") + " " + (n.data("lname") || "")).toLowerCase();
      return searchWords.every(word => fullName.includes(word));
    });

    // თუ ძებნა ახალია ან შეიცვალა — თავიდან დავაყენოთ ინდექსი
    const lastSearchNames = lastResultsRef.current.map(n => n.id()).join(",");
    const newSearchNames = found.map(n => n.id()).join(",");
    if (lastSearchNames !== newSearchNames) {
      lastResultsRef.current = found.toArray();
      currentIndexRef.current = 0;
    }

    // თუ არსებობს ნაპოვნი
    if (lastResultsRef.current.length > 0) {
      // მივიღოთ მიმდინარე ელემენტი
      const currentNode = lastResultsRef.current[currentIndexRef.current];

      // მოვნიშნოთ და გავზუმოთ
      currentNode.addClass("highlighted");
      cyInstance.animate({
        center: { eles: currentNode },
        zoom: 1.5,
      });

      // ინდექსი გადავიყვანოთ შემდეგზე (ციკლურად)
      currentIndexRef.current =
        (currentIndexRef.current + 1) % lastResultsRef.current.length;
    }
  };
  useEffect(() => {
    if (!cyInstance) return;

    const handleNodeClick = (evt) => {
      const clickedNode = evt.target;

      // წინა highlighted–ები წავშალოთ
      cyInstance.nodes().removeClass("highlighted");

      // სელექცია ჩვეულებრივად
      cyInstance.nodes().unselect();
      clickedNode.select();

      setMenuOpen(false);
      setPopupDismissed(false);
      if (clickedNode.data('role') !== 'MergePoint') {
        setSelectedPersonId(Number(clickedNode.id()));
      } else {
        setSelectedPersonId(null);
      }
    };

    cyInstance.on('tap', 'node', handleNodeClick);

    // Cleanup
    return () => {
      cyInstance.off('tap', 'node', handleNodeClick);
    };
  }, [cyInstance]);

  useEffect(() => {
    if (!cyInstance) return;

    const bumpViewportTick = () => setViewportTick(t => t + 1);
    cyInstance.on('pan zoom', bumpViewportTick);

    return () => {
      cyInstance.off('pan zoom', bumpViewportTick);
    };
  }, [cyInstance]);

  return (
    <div style={layoutContainerStyle}>
      <div style={headerStyle}>
        <Filters
          allLnames={allLnames}
          selectedLname={selectedLname}
          onFilterChange={handleLnameFilter}
        />
        <SearchInputs
          peopleList={allElements.filter(m => m.role != 'MergePoint')}
          setElements={setElements}
          setConnections={setConnections}
        />
        <CountDisplay count={filteredCount} />
        <label style={popupToggleStyle}>
          <input
            type="checkbox"
            checked={showInfoPopup}
            onChange={(e) => setShowInfoPopup(e.target.checked)}
          />
          ინფო პოპაპი
        </label>
        <AuthStatus />

        <div className="node-search-container">
          <input
            type="text"
            placeholder="ძებნა..."
            id="nodeSearch"
            className="node-search-input"
          />
          <button
            className="node-search-button"
            onClick={handleSearchGOTO}
          >
            Go
          </button>
        </div>
      </div>
      <div className="graph-container">
        <div id="cy"></div>
        {/* <div id="cy-preview" className={previewOpen ? 'open' : "closed"}></div> */}
        <div id="cy-preview" style={previewStyle}></div>
        <button
          className={`toggle-preview-btn ${previewOpen ? 'open' : 'closed'}`}
          onClick={togglePreview}
        >
          {previewOpen ? '⟨' : '⟩'}
        </button>
      </div>

      {(() => {
        const pos = getNodeScreenPosition(selectedPersonId);
        if (!pos) return null;
        const member = allElements.find(m => m.id === selectedPersonId);

        return (
          <>
            {isAdmin && (
              <button
                style={nodeActionButtonStyle(pos)}
                onClick={() => setMenuOpen(true)}
                title="მოქმედებები"
              >
                ⚙
              </button>
            )}

            {isAdmin && menuOpen && (
              <NodeActionsMenu
                position={{ x: pos.x + 20, y: pos.y }}
                onClose={() => setMenuOpen(false)}
                onSelect={(action) => {
                  setMenuOpen(false);
                  if (action === 'edit') {
                    if (member) setEditingMember(member);
                  } else if (action === 'delete') {
                    const name = member ? `${member.fname || ''} ${member.lname || ''}`.trim() : 'ეს პიროვნება';
                    if (window.confirm(`დარწმუნებული ხართ, რომ გსურთ წაშალოთ „${name}“? მისი ყველა კავშირი წაიშლება.`)) {
                      removeMember(selectedPersonId, allConnections)
                        .then(() => {
                          setSelectedPersonId(null);
                          loadTree();
                        })
                        .catch(err => alert(err.message));
                    }
                  } else {
                    setRelativeAction({ kind: action, personId: selectedPersonId });
                  }
                }}
              />
            )}

            {showInfoPopup && !popupDismissed && member && (
              <NodeInfoPopup
                position={pos}
                member={member}
                onClose={() => setPopupDismissed(true)}
              />
            )}
          </>
        );
      })()}

      {relativeAction && (
        <AddRelativeModal
          kind={relativeAction.kind}
          personId={relativeAction.personId}
          members={allElements}
          relationships={allConnections}
          onClose={() => setRelativeAction(null)}
          onSuccess={() => {
            setRelativeAction(null);
            setSelectedPersonId(null);
            loadTree();
          }}
        />
      )}

      {editingMember && (
        <EditMemberModal
          member={editingMember}
          onClose={() => setEditingMember(null)}
          onSuccess={() => {
            setEditingMember(null);
            setSelectedPersonId(null);
            loadTree();
          }}
        />
      )}
    </div>

  );
};

export default FamilyTreeGraph;
