import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import {
  authPageStyle,
  authCardStyle,
  authTitleStyle,
  authFormStyle,
  authInputStyle,
  authButtonStyle,
  authErrorStyle,
  authSwitchStyle,
} from '../styles/authStyles';

const LoginPage = () => {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSubmitting(true);
    try {
      await login(username, password);
      navigate('/');
    } catch (err) {
      setError(err.message);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div style={authPageStyle}>
      <div style={authCardStyle}>
        <h1 style={authTitleStyle}>ავტორიზაცია</h1>
        <form style={authFormStyle} onSubmit={handleSubmit}>
          <input
            style={authInputStyle}
            type="text"
            placeholder="მომხმარებელი"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            autoComplete="username"
            required
          />
          <input
            style={authInputStyle}
            type="password"
            placeholder="პაროლი"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            autoComplete="current-password"
            required
          />
          {error && <p style={authErrorStyle}>{error}</p>}
          <button style={authButtonStyle} type="submit" disabled={submitting}>
            {submitting ? '...' : 'შესვლა'}
          </button>
        </form>
        <div style={authSwitchStyle}>
          <Link to="/">← უკან ხესთან დაბრუნება</Link>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;
