import { getToken } from './authService';

//const API_BASE = 'https://localhost:7261/api';
const API_BASE = 'https://aleko279.runasp.net/api';

const parseErrorMessage = async (res) => {
  try {
    const data = await res.json();
    return data.message || (typeof data === 'string' ? data : 'დაფიქსირდა შეცდომა');
  } catch {
    return 'დაფიქსირდა შეცდომა';
  }
};

const authRequest = async (path, options = {}) => {
  const res = await fetch(`${API_BASE}${path}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${getToken()}`,
      ...options.headers,
    },
  });

  if (!res.ok) {
    throw new Error(await parseErrorMessage(res));
  }

  if (res.status === 204) return null;
  return res.json();
};

export const getRelationshipTypes = () => authRequest('/Relationship/types');

export const createMember = (member) =>
  authRequest('/Member', { method: 'POST', body: JSON.stringify(member) });

export const updateMember = (id, member) =>
  authRequest(`/Member/${id}`, { method: 'PUT', body: JSON.stringify(member) });

export const deleteMember = (id) =>
  authRequest(`/Member/${id}`, { method: 'DELETE' });

export const createRelationship = (relationship) =>
  authRequest('/Relationship', { method: 'POST', body: JSON.stringify(relationship) });

export const deleteRelationship = (id) =>
  authRequest(`/Relationship/${id}`, { method: 'DELETE' });
