import React from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { authStatusStyle, authLogoutButtonStyle } from '../styles/authStyles';

const AuthStatus = () => {
  const { user, isAuthenticated, logout } = useAuth();

  if (!isAuthenticated) {
    return (
      <div style={authStatusStyle}>
        <Link to="/login">ადმინად შესვლა</Link>
      </div>
    );
  }

  return (
    <div style={authStatusStyle}>
      <span>{user}</span>
      <button style={authLogoutButtonStyle} onClick={logout}>
        გამოსვლა
      </button>
    </div>
  );
};

export default AuthStatus;
