const AUTH_API_BASE = 'https://localhost:7261/api/Auth';
//const AUTH_API_BASE = 'https://aleko279.runasp.net/api/Auth';

const STORAGE_KEY = 'ft_auth';

const parseErrorMessage = async (res) => {
  try {
    const data = await res.json();
    return data.message || 'დაფიქსირდა შეცდომა';
  } catch {
    return 'დაფიქსირდა შეცდომა';
  }
};

export const login = async (username, password) => {
  const res = await fetch(`${AUTH_API_BASE}/Login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ username, password }),
  });

  if (!res.ok) {
    throw new Error(await parseErrorMessage(res));
  }

  const data = await res.json();
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  return data;
};

export const logout = () => {
  localStorage.removeItem(STORAGE_KEY);
};

export const getAuth = () => {
  const raw = localStorage.getItem(STORAGE_KEY);
  if (!raw) return null;

  try {
    const auth = JSON.parse(raw);
    if (auth.expiresAt && new Date(auth.expiresAt) <= new Date()) {
      localStorage.removeItem(STORAGE_KEY);
      return null;
    }
    return auth;
  } catch {
    return null;
  }
};

export const getToken = () => getAuth()?.token ?? null;
