import { createMember, createRelationship, deleteMember, deleteRelationship } from './adminService';

const SPOUSE_TYPE_ID = 1;
const CHILD_TYPE_ID = 2;

const isMergePoint = (members, id) => members.find((m) => m.id === id)?.role === 'MergePoint';

const findUnions = (personId, members, relationships) =>
  relationships.filter((r) => r.source === personId && isMergePoint(members, r.target));

const findParentRelationship = (personId, members, relationships) =>
  relationships.find((r) => r.target === personId && isMergePoint(members, r.source));

const otherSpouseName = (mergePointId, excludePersonId, members, relationships) => {
  const rel = relationships.find((r) => r.target === mergePointId && r.source !== excludePersonId);
  const spouse = rel && members.find((m) => m.id === rel.source);
  return spouse ? `${spouse.fname || ''} ${spouse.lname || ''}`.trim() : null;
};

export const findUnionOptions = (personId, members, relationships) =>
  findUnions(personId, members, relationships).map((r) => ({
    mergePointId: r.target,
    label: otherSpouseName(r.target, personId, members, relationships) || 'უცნობი მეუღლე',
  }));

export const findParentMergePointInfo = (personId, members, relationships) => {
  const rel = findParentRelationship(personId, members, relationships);
  if (!rel) return { mergePointId: null, spouseCount: 0 };
  const spouseCount = relationships.filter((r) => r.target === rel.source).length;
  return { mergePointId: rel.source, spouseCount };
};

export const addSpouse = async (personId, memberData) => {
  const newMember = await createMember(memberData);
  const mergePoint = await createMember({ role: 'MergePoint' });
  await createRelationship({ source: personId, target: mergePoint.id, relationshipTypeId: SPOUSE_TYPE_ID });
  await createRelationship({ source: newMember.id, target: mergePoint.id, relationshipTypeId: SPOUSE_TYPE_ID });
  return newMember;
};

export const removeMember = async (personId, relationships) => {
  const touching = relationships.filter((r) => r.source === personId || r.target === personId);
  for (const rel of touching) {
    await deleteRelationship(rel.id);
  }
  await deleteMember(personId);
};

export const addChild = async (personId, memberData, members, relationships, chosenMergePointId) => {
  const unions = findUnions(personId, members, relationships);
  let mergePointId = chosenMergePointId;

  if (!mergePointId) {
    if (unions.length === 1) {
      mergePointId = unions[0].target;
    } else if (unions.length === 0) {
      const mergePoint = await createMember({ role: 'MergePoint' });
      await createRelationship({ source: personId, target: mergePoint.id, relationshipTypeId: SPOUSE_TYPE_ID });
      mergePointId = mergePoint.id;
    } else {
      throw new Error('აირჩიეთ კავშირი, რომელსაც შვილი ეკუთვნის');
    }
  }

  const newMember = await createMember(memberData);
  await createRelationship({ source: mergePointId, target: newMember.id, relationshipTypeId: CHILD_TYPE_ID });
  return newMember;
};

export const addParent = async (personId, memberData, members, relationships) => {
  const { mergePointId, spouseCount } = findParentMergePointInfo(personId, members, relationships);

  if (mergePointId && spouseCount >= 2) {
    throw new Error('ორივე მშობელი უკვე დამატებულია');
  }

  const newMember = await createMember(memberData);

  if (mergePointId) {
    await createRelationship({ source: newMember.id, target: mergePointId, relationshipTypeId: SPOUSE_TYPE_ID });
  } else {
    const mergePoint = await createMember({ role: 'MergePoint' });
    await createRelationship({ source: newMember.id, target: mergePoint.id, relationshipTypeId: SPOUSE_TYPE_ID });
    await createRelationship({ source: mergePoint.id, target: personId, relationshipTypeId: CHILD_TYPE_ID });
  }

  return newMember;
};
