import React from 'react';
import {
  infoPopupStyle,
  infoPopupHeaderStyle,
  infoPopupNameStyle,
  infoPopupCloseStyle,
  infoPopupRowStyle,
  infoPopupLabelStyle,
} from '../styles/addRelativeStyles';

const FIELD_LABELS = [
  ['nName', 'მეტსახელი'],
  ['gender', 'სქესი'],
  ['birthDate', 'დაბადება'],
  ['deathDate', 'გარდაცვალება'],
  ['birthPlace', 'დაბადების ადგილი'],
  ['role', 'როლი'],
];

const NodeInfoPopup = ({ position, member, onClose }) => {
  if (!member) return null;

  const fullName = `${member.fname || ''} ${member.lname || ''}`.trim() || 'უცნობი';

  return (
    <div style={infoPopupStyle(position)}>
      <div style={infoPopupHeaderStyle}>
        <span style={infoPopupNameStyle}>{fullName}</span>
        <button style={infoPopupCloseStyle} onClick={onClose} title="დახურვა">
          ×
        </button>
      </div>
      {FIELD_LABELS.filter(([field]) => member[field]).map(([field, label]) => (
        <div key={field} style={infoPopupRowStyle}>
          <span style={infoPopupLabelStyle}>{label}</span>
          <span>{member[field]}</span>
        </div>
      ))}
    </div>
  );
};

export default NodeInfoPopup;
